import json
from collections import Counter
from dataclasses import dataclass
from datetime import datetime, timezone


@dataclass(frozen=True)
class Event:
    ts: datetime
    service: str
    level: str
    msg: str = ""


def to_utc(ts):
    """Naive timestamps are UTC (legacy collectors); aware ones are converted."""
    if ts.tzinfo is None:
        return ts.replace(tzinfo=timezone.utc)
    return ts.astimezone(timezone.utc)


def parse_line(line):
    raw = json.loads(line)
    return Event(
        ts=to_utc(datetime.fromisoformat(raw["ts"])),
        service=raw["service"],
        level=raw["level"],
        msg=raw.get("msg", ""),
    )


def read_events(path):
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            if line.strip():
                yield parse_line(line)


def count_events(events, since=None):
    if since is not None:
        events = (event for event in events if event.ts >= since)
    return Counter((event.service, event.level) for event in events)

