import argparse
import sys
from datetime import datetime

from .events import count_events, read_events, to_utc


def parse_since(value):
    try:
        return to_utc(datetime.fromisoformat(value))
    except ValueError:
        raise argparse.ArgumentTypeError(
            f"invalid --since value {value!r}: expected an ISO date or datetime, "
            "e.g. 2024-03-10 or 2024-03-10T12:00:00+00:00"
        )


def build_parser():
    parser = argparse.ArgumentParser(prog="evlog")
    commands = parser.add_subparsers(dest="command", required=True)
    report = commands.add_parser("report", help="count events per service and level")
    report.add_argument("path", help="events file (JSON lines)")
    report.add_argument(
        "--since",
        type=parse_since,
        metavar="WHEN",
        help="only count events at or after this ISO date/datetime "
        "(a date means 00:00 UTC; times without an offset are UTC)",
    )
    return parser


def render(counts):
    lines = [f"{service} {level} {n}" for (service, level), n in sorted(counts.items())]
    lines.append(f"total {sum(counts.values())}")
    return "\n".join(lines)


def main(argv=None, out=None):
    out = out or sys.stdout
    parser = build_parser()
    args = parser.parse_args(argv)
    if args.command == "report":
        try:
            counts = count_events(read_events(args.path), since=args.since)
        except OSError as exc:
            parser.error(f"cannot read {args.path}: {exc.strerror or exc}")
        print(render(counts), file=out)
    return 0

